      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 2.5 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'INVALID', qty: 1 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'UNKNOWN_SKU');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'sent',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'NOT_DRAFT');
  });

  it('does not mutate the original invoice', () => {
